import org.junit.jupiter.api.Test;

/**
 * Safety and boundary tests for finite-value filter anchors.
 */
public class FiniteFilterOptimizerTest {

	@Test
	public void sameTermUsesExactRdfTermIdentityWhileEqualityRejectsNumericValues() {
		SimpleValueFactory valueFactory = SimpleValueFactory.getInstance();
		Literal lexicalOne = valueFactory.createLiteral("01", XSD.INTEGER);
		Literal lexicalTwo = valueFactory.createLiteral("1", XSD.INTEGER);

		TupleExpr sameTermQuery = sameTermOrQuery(lexicalOne, lexicalTwo);
		new DisjunctiveConstraintOptimizer().optimize(sameTermQuery, null, EmptyBindingSet.getInstance());

		assertThat(findValuesAnchors(sameTermQuery)).singleElement()
				.satisfies(anchor -> assertThat(anchor.getBindingSets()).hasSize(2));

		Filter equalityFilter = new Filter(pattern(),
				new Compare(Var.of("o"), new ValueConstant(lexicalOne), Compare.CompareOp.EQ));
		QueryRoot equalityQuery = new QueryRoot(equalityFilter);
		new FilterInValuesOptimizer().optimize(equalityQuery, null, EmptyBindingSet.getInstance());

		assertThat(findValuesAnchors(equalityQuery))
				.as("value equality must not be replaced by exact RDF-term SameTerm rows for numeric literals")
				.isEmpty();
	}

	@Test
	public void listMembershipRejectsNumericValueEqualityAnchors() {
		SimpleValueFactory valueFactory = SimpleValueFactory.getInstance();
		ListMemberOperator condition = new ListMemberOperator();
		condition.addArgument(Var.of("o"));
		condition.addArgument(new ValueConstant(valueFactory.createLiteral("01", XSD.INTEGER)));
		condition.addArgument(new ValueConstant(valueFactory.createLiteral("1", XSD.INTEGER)));
		QueryRoot root = new QueryRoot(new Filter(pattern(), condition));

		new FilterInValuesOptimizer().optimize(root, null, EmptyBindingSet.getInstance());

		assertThat(findValuesAnchors(root))
				.as("IN uses value-equality and must retain numeric comparison semantics")
				.isEmpty();
	}

	@Test
	public void listMembershipHonorsTheSixtyFourValueCap() {
		Optional<BindingSetAssignment> capped = anchorForListMembership(64);
		assertThat(capped).isPresent();
		assertThat(capped.orElseThrow().getBindingSets()).hasSize(64);
		assertThat(anchorForListMembership(65)).isEmpty();
	}

	@Test
	public void sameTermOrHonorsTheSixtyFourDistinctValueCap() {
		assertAll(
				() -> {
					Optional<BindingSetAssignment> capped = anchorForSameTermOr(finiteValues(64));
					assertThat(capped).as("64 distinct SameTerm values remain within the finite-anchor cap")
							.isPresent();
					assertThat(capped.orElseThrow().getBindingSets()).hasSize(64);
				},
				() -> assertThat(anchorForSameTermOr(finiteValues(65)))
						.as("65 distinct SameTerm values exceed the finite-anchor cap")
						.isEmpty(),
				() -> {
					List<Value> repeatedBeyondTheCap = new ArrayList<>(finiteValues(64));
					repeatedBeyondTheCap.add(repeatedBeyondTheCap.get(0));
					repeatedBeyondTheCap.add(repeatedBeyondTheCap.get(1));
					repeatedBeyondTheCap.add(repeatedBeyondTheCap.get(0));
					Optional<BindingSetAssignment> deduplicated = anchorForSameTermOr(repeatedBeyondTheCap);
					assertThat(deduplicated)
							.as("repeated SameTerm disjuncts count after exact-value deduplication")
							.isPresent();
					assertThat(deduplicated.orElseThrow().getBindingSets()).hasSize(64);
				});
	}

	@Test
	public void doesNotAnchorAValueFromAnOptionalOnlyOperand() {
		StatementPattern left = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("left"));
		StatementPattern optional = new StatementPattern(Var.of("s"), Var.of("q"), Var.of("o"));
		Filter filter = new Filter(new LeftJoin(left, optional),
				new SameTerm(Var.of("o"), new ValueConstant(SimpleValueFactory.getInstance().createIRI("urn:test:o"))));
		QueryRoot root = new QueryRoot(filter);

		new FilterInValuesOptimizer().optimize(root, null, EmptyBindingSet.getInstance());

		assertThat(findValuesAnchors(root))
				.as("an optional-only variable is not assured at the finite-filter scope")
				.isEmpty();
	}

	private static Optional<BindingSetAssignment> anchorForListMembership(int valueCount) {
		ListMemberOperator condition = new ListMemberOperator();
		condition.addArgument(Var.of("o"));
		for (int i = 0; i < valueCount; i++) {
			condition.addArgument(new ValueConstant(SimpleValueFactory.getInstance().createLiteral("value-" + i)));
		}
		QueryRoot root = new QueryRoot(new Filter(pattern(), condition));

		new FilterInValuesOptimizer().optimize(root, null, EmptyBindingSet.getInstance());

		return findValuesAnchors(root).stream().findFirst();
	}

	private static Optional<BindingSetAssignment> anchorForSameTermOr(List<Value> values) {
		QueryRoot root = (QueryRoot) sameTermOrQuery(values);
		new DisjunctiveConstraintOptimizer().optimize(root, null, EmptyBindingSet.getInstance());
		return findValuesAnchors(root).stream().findFirst();
	}

	private static TupleExpr sameTermOrQuery(Value left, Value right) {
		ValueExpr leftArg = new ValueConstant(left);
		ValueExpr rightArg = new ValueConstant(right);
		Or condition = new Or(new SameTerm(Var.of("o"), leftArg), new SameTerm(rightArg, Var.of("o")));
		return new QueryRoot(new Filter(pattern(), condition));
	}

	private static TupleExpr sameTermOrQuery(List<Value> values) {
		if (values.size() < 2) {
			throw new IllegalArgumentException("at least two finite terms are required");
		}
		Or condition = new Or(new SameTerm(Var.of("o"), new ValueConstant(values.get(0))),
				new SameTerm(Var.of("o"), new ValueConstant(values.get(1))));
		for (Value value : values.subList(2, values.size())) {
			condition = new Or(condition, new SameTerm(Var.of("o"), new ValueConstant(value)));
		}
		return new QueryRoot(new Filter(pattern(), condition));
	}

	private static List<Value> finiteValues(int count) {
		List<Value> values = new ArrayList<>(count);
		for (int i = 0; i < count; i++) {
			values.add(SimpleValueFactory.getInstance().createIRI("urn:test:finite-" + i));
		}
		return values;
	}

	private static StatementPattern pattern() {
		return new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
	}

	private static List<BindingSetAssignment> findValuesAnchors(TupleExpr tupleExpr) {
		List<BindingSetAssignment> assignments = new ArrayList<>();
		tupleExpr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof BindingSetAssignment assignment) {
					assignments.add(assignment);
				}
				super.meetNode(node);
			}
		});
		return assignments;
	}
}
